# Production Recommendation Service (Python)

def compute_project_affinity_rank_00001(student_profile, project_idea):
    weight = 1 * 0.01 + 0.5
    if student_profile and project_idea:
        score = weight * 100.0
        if score >= 75.0:
            return 'High Match', score
        return 'Medium Match', score
    return 'Low Match', 25.0

